alter table public.exercises add column required_equipment jsonb not null default '[]'::jsonb;
alter table public.exercises add column illustration_author text;
alter table public.exercises add column illustration_style text;
update public.exercises set required_equipment=jsonb_build_array(equipment);
update public.exercises set required_equipment='["barbell", "bench", "squat_rack"]'::jsonb where slug='barbell-bench-press';
update public.exercises set required_equipment='["dumbbell", "incline_bench"]'::jsonb where slug='incline-dumbbell-press';
update public.exercises set required_equipment='["chest_press"]'::jsonb where slug='machine-chest-press';
update public.exercises set required_equipment='["lat_pulldown"]'::jsonb where slug='lat-pulldown';
update public.exercises set required_equipment='["seated_row"]'::jsonb where slug='cable-row';
update public.exercises set required_equipment='["dumbbell", "bench"]'::jsonb where slug='dumbbell-row';
update public.exercises set required_equipment='["dumbbell", "bench"]'::jsonb where slug='dumbbell-shoulder-press';
update public.exercises set required_equipment='["dumbbell", "bench"]'::jsonb where slug='dumbbell-skullcrusher';
update public.exercises set required_equipment='["barbell", "squat_rack"]'::jsonb where slug='back-squat';
update public.exercises set required_equipment='["leg_press"]'::jsonb where slug='leg-press';
update public.exercises set required_equipment='["dumbbell", "bench"]'::jsonb where slug='bulgarian-split-squat';
update public.exercises set required_equipment='["leg_extension"]'::jsonb where slug='leg-extension';
update public.exercises set required_equipment='["leg_curl"]'::jsonb where slug='leg-curl';
update public.exercises set required_equipment='["barbell", "bench"]'::jsonb where slug='hip-thrust';
update public.exercises set required_equipment='["dumbbell", "bench"]'::jsonb where slug='seated-calf-raise';
create function public.can_use_exercise(p_exercise uuid) returns boolean language sql stable security invoker set search_path='' as $$
 select exists(select 1 from public.exercises e where e.id=p_exercise and not exists(select 1 from jsonb_array_elements_text(e.required_equipment) requirement where not exists(select 1 from public.available_equipment a where a.user_id=auth.uid() and a.is_available and a.equipment_type=requirement)));
$$;
revoke all on function public.can_use_exercise(uuid) from public,anon;
grant execute on function public.can_use_exercise(uuid) to authenticated;
create or replace function public.resolve_recommendation(p_id uuid,p_accept boolean) returns void language plpgsql security invoker set search_path='' as $$
declare r public.recommendations; t public.nutrition_targets; pg public.training_programs; pe public.workout_template_exercises; ex public.exercises; np uuid; new_ex public.exercises; value numeric; d date:=(now() at time zone 'Africa/Blantyre')::date; begin
 select * into strict r from public.recommendations where id=p_id for update;
 if r.status=(case when p_accept then 'accepted' else 'rejected' end) then return;end if;
 if r.status<>'pending' then raise exception 'RECOMMENDATION_ALREADY_RESOLVED';end if;
 if r.source_period_end<d-14 then update public.recommendations set status='expired' where id=r.id;return;end if;
 if p_accept and r.type='nutrition_adjustment' then
 select * into strict t from public.nutrition_targets where user_id=auth.uid() and effective_to is null for update;
 if t.id::text<>r.payload->>'targetId' then raise exception 'CONFLICT';end if;
 update public.nutrition_targets set effective_to=greatest(effective_from,d) where id=t.id;
 insert into public.nutrition_targets(user_id,version,effective_from,calories_target,protein_target_g,carbs_target_g,fat_target_g,reason,created_from_recommendation_id)
 values(auth.uid(),t.version+1,d,r.recommended_value,t.protein_target_g,greatest(0,t.carbs_target_g+round((r.recommended_value-t.calories_target)/4)),t.fat_target_g,r.reason,r.id);
 elsif p_accept and r.type in ('exercise_load_progression','training_volume_adjustment','deload','exercise_substitution') then
 select * into strict pg from public.training_programs where user_id=auth.uid() and effective_to is null for update;
 if pg.id::text<>r.payload->>'programId' then raise exception 'CONFLICT';end if;
 if r.payload->>'action'='restore' then
 if pg.phase<>'deload' or pg.resume_program_id::text<>r.payload->>'restoreFromProgramId' then raise exception 'CONFLICT';end if;
 np:=app_private.clone_program(pg.id,r.id);
 update public.workout_template_exercises changed set sets=original.sets
 from public.workout_templates changed_template,public.workout_template_exercises original,public.workout_templates original_template,public.program_weeks original_week
 where changed.workout_template_id=changed_template.id and original.workout_template_id=original_template.id and original_template.program_week_id=original_week.id and original_week.training_program_id=pg.resume_program_id and changed_template.lineage_id=original_template.lineage_id and changed.sort_order=original.sort_order and changed_template.program_week_id in(select id from public.program_weeks where training_program_id=np);
 update public.training_programs set phase='base',planned_until=null,resume_program_id=null where id=np;
 elsif r.type='deload' then
 if pg.phase='deload' then raise exception 'CONFLICT';end if;
 np:=app_private.clone_program(pg.id,r.id);
 update public.training_programs set phase='deload',planned_until=d+7,resume_program_id=pg.id where id=np;
 update public.workout_template_exercises set sets=greatest(1,ceil(sets::numeric/2)::integer) where workout_template_id in(select wt.id from public.workout_templates wt join public.program_weeks w on w.id=wt.program_week_id where w.training_program_id=np);
 else
 select e.* into strict pe from public.workout_template_exercises e join public.workout_templates wt on wt.id=e.workout_template_id join public.program_weeks w on w.id=wt.program_week_id where e.id::text=r.payload->>'templateExerciseId' and w.training_program_id=pg.id;
 select * into strict ex from public.exercises where id=pe.exercise_id;
 value:=r.recommended_value;
 if r.type='exercise_load_progression' then
 if value is null or value<=pe.planned_weight_kg or not exists(select 1 from public.available_equipment where user_id=auth.uid() and equipment_type=ex.equipment and is_available) or not exists(select 1 from public.gym_load_options where user_id=auth.uid() and (exercise_id=ex.id or (exercise_id is null and equipment_type=ex.equipment)) and value between minimum_kg and maximum_kg and abs(mod(value-minimum_kg,increment_kg))<0.00001) then raise exception 'INVALID_INPUT';end if;
 elsif r.type='training_volume_adjustment' then
 if value is null or value<>floor(value) or value<1 or value>10 or abs(value-pe.sets)>1 then raise exception 'INVALID_INPUT';end if;
 elsif r.type='exercise_substitution' then
 select * into strict new_ex from public.exercises where id::text=r.payload->>'replacementExerciseId' and is_active and primary_muscle=ex.primary_muscle and public.can_use_exercise(public.exercises.id) and not exists(select 1 from public.workout_template_exercises existing where existing.workout_template_id=pe.workout_template_id and existing.exercise_id=public.exercises.id and existing.id<>pe.id);
 end if;
 np:=app_private.clone_program(pg.id,r.id);
 update public.workout_template_exercises set
 planned_weight_kg=case when r.type='exercise_load_progression' then value when r.type='exercise_substitution' then 0 else planned_weight_kg end,
 sets=case when r.type='training_volume_adjustment' then value::integer else sets end,
 exercise_id=case when r.type='exercise_substitution' then new_ex.id else exercise_id end,
 rep_min=case when r.type='exercise_substitution' then new_ex.default_rep_min else rep_min end,
 rep_max=case when r.type='exercise_substitution' then new_ex.default_rep_max else rep_max end,
 lineage_id=case when r.type='exercise_substitution' then gen_random_uuid() else lineage_id end
 where lineage_id=pe.lineage_id and workout_template_id in(select wt.id from public.workout_templates wt join public.program_weeks w on w.id=wt.program_week_id where w.training_program_id=np);
 end if;
 update public.recommendations set status='expired' where user_id=auth.uid() and status='pending' and id<>r.id and payload->>'programId'=pg.id::text;
 end if;
 update public.recommendations set status=case when p_accept then 'accepted' else 'rejected' end,accepted_at=case when p_accept then now() end,rejected_at=case when not p_accept then now() end where id=r.id;
 if p_accept then perform public.refresh_completion(d);end if;
end $$;
create or replace function public.start_workout(p_template uuid) returns uuid language plpgsql security invoker set search_path='' as $$
declare result uuid; wt public.workout_templates; d date:=(now() at time zone 'Africa/Blantyre')::date; begin
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,2));
 select id into result from public.workout_sessions where user_id=auth.uid() and status='in_progress';
 if result is not null then return result; end if;
 select * into strict wt from public.workout_templates where id=p_template for update;
 if exists(select 1 from public.workout_template_exercises p join public.exercises e on e.id=p.exercise_id where p.workout_template_id=wt.id and not public.can_use_exercise(e.id)) then raise exception 'EQUIPMENT_UNAVAILABLE';end if;
 if wt.day_of_week<>extract(dow from d)::integer or not exists(select 1 from public.program_weeks w join public.training_programs p on p.id=w.training_program_id where w.id=wt.program_week_id and p.effective_to is null) then raise exception 'CONFLICT'; end if;
 select id into result from public.workout_sessions where user_id=auth.uid() and workout_template_id=p_template and session_date=d;
 if result is not null then
 update public.workout_sessions set status='in_progress' where id=result and status='abandoned';
 return result;
 end if;
 insert into public.workout_sessions(user_id,workout_template_id,session_date) values(auth.uid(),p_template,d) returning id into result;
 return result;
end $$;

-- Retain upper/lower templates when expanding a previously reduced schedule.
create or replace function public.save_settings(p_settings jsonb) returns void language plpgsql security invoker set search_path='' as $$
declare days integer[]; previous_days integer[]; old public.training_programs; current_profile public.profiles; count_days integer; np uuid; nw uuid; nt uuid; source_ids uuid[]; wt public.workout_templates; i integer; selected_equipment jsonb; policy jsonb; desired_name text; begin
 select * into strict current_profile from public.profiles where user_id=auth.uid() for update;
 select array_agg(value::integer order by ord) into days from jsonb_array_elements_text(p_settings->'days') with ordinality as x(value,ord);
 count_days:=array_length(days,1);
 if count_days is null or count_days<1 or count_days>7 or (select count(distinct d) from unnest(days) d)<>count_days or exists(select 1 from unnest(days) d where d<0 or d>6) then raise exception 'INVALID_INPUT';end if;
 policy:=coalesce(p_settings->'completion_policy',(select completion_policy from public.user_preferences where user_id=auth.uid()));
 if policy is null or exists(select 1 from unnest(array['weight','nutrition','workout','recovery','water']) key where jsonb_typeof(policy->key) is distinct from 'boolean') or not ((policy->>'weight')::boolean or (policy->>'nutrition')::boolean or (policy->>'recovery')::boolean or (policy->>'water')::boolean) then raise exception 'INVALID_INPUT';end if;
 update public.profiles set first_name=p_settings->>'first_name',water_target_ml=(p_settings->>'water_target_ml')::integer,training_days_per_week=count_days,
 height_cm=coalesce((p_settings->>'height_cm')::numeric,height_cm),goal_weight_kg=coalesce((p_settings->>'goal_weight_kg')::numeric,goal_weight_kg),
 target_date=case when p_settings?'target_date' then nullif(p_settings->>'target_date','')::date else target_date end,
 training_experience=coalesce(p_settings->>'training_experience',training_experience),updated_at=now() where user_id=auth.uid();
 update public.user_preferences set diet_type=p_settings->>'diet_type',budget_mode=p_settings->>'budget_mode',completion_policy=policy where user_id=auth.uid();
 if p_settings?'equipment' then
 selected_equipment:=p_settings->'equipment';
 if jsonb_array_length(selected_equipment)<1 or not selected_equipment?'bodyweight' or exists(select 1 from jsonb_array_elements_text(selected_equipment) e where e not in ('bodyweight','barbell','dumbbell','cable','machine','pullup_bar','bench','incline_bench','squat_rack','lat_pulldown','seated_row','leg_press','leg_extension','leg_curl','chest_press')) then raise exception 'INVALID_INPUT';end if;
 update public.available_equipment set is_available=false where user_id=auth.uid();
 insert into public.available_equipment(user_id,equipment_type,is_available) select auth.uid(),value,true from jsonb_array_elements_text(selected_equipment)
 on conflict(user_id,equipment_type) do update set is_available=true;
 end if;
 select * into strict old from public.training_programs where user_id=auth.uid() and effective_to is null for update;
 select array_agg(saved.day_of_week order by saved.sort_order),array_agg(saved.id order by saved.sort_order) into previous_days,source_ids from public.workout_templates saved join public.program_weeks w on w.id=saved.program_week_id where w.training_program_id=old.id;
 if days is distinct from previous_days then
 if old.phase='deload' then raise exception 'DELOAD_ACTIVE';end if;
 if exists(select 1 from public.workout_sessions where user_id=auth.uid() and status='in_progress') then raise exception 'WORKOUT_IN_PROGRESS';end if;
 update public.training_programs set effective_to=greatest(effective_from,(now() at time zone 'Africa/Blantyre')::date) where id=old.id;
 insert into public.training_programs(user_id,version,name,phase,effective_from) values(auth.uid(),old.version+1,old.name,'base',(now() at time zone 'Africa/Blantyre')::date) returning id into np;
 insert into public.program_weeks(user_id,training_program_id,week_number) values(auth.uid(),np,1) returning id into nw;
 for i in 1..count_days loop
 desired_name:=case when mod(i,2)=1 then 'Upper' else 'Lower' end||' '||chr(65+(i-1)/2);
 select saved.* into wt from public.workout_templates saved join public.program_weeks sw on sw.id=saved.program_week_id join public.training_programs sp on sp.id=sw.training_program_id where sp.user_id=auth.uid() and sp.id<>np and sp.phase<>'deload' and saved.name=desired_name order by sp.version desc limit 1;
 if wt.id is null then
 select saved.* into strict wt from public.workout_templates saved join public.program_weeks sw on sw.id=saved.program_week_id join public.training_programs sp on sp.id=sw.training_program_id where sp.user_id=auth.uid() and sp.id<>np and sp.phase<>'deload' and split_part(saved.name,' ',1)=split_part(desired_name,' ',1) order by sp.version desc,saved.sort_order limit 1;
 end if;
 insert into public.workout_templates(user_id,program_week_id,name,day_of_week,sort_order,estimated_minutes,lineage_id)
 values(auth.uid(),nw,desired_name,days[i],i,wt.estimated_minutes,case when wt.name=desired_name then wt.lineage_id else gen_random_uuid() end) returning id into nt;
 insert into public.workout_template_exercises(user_id,workout_template_id,exercise_id,sort_order,sets,rep_min,rep_max,target_rir,rest_seconds,planned_weight_kg,lineage_id)
 select auth.uid(),nt,exercise_id,sort_order,sets,rep_min,rep_max,target_rir,rest_seconds,planned_weight_kg,case when wt.name=desired_name then lineage_id else gen_random_uuid() end from public.workout_template_exercises where workout_template_id=wt.id;
 end loop;
 update public.recommendations set status='expired' where user_id=auth.uid() and status='pending' and payload->>'programId'=old.id::text;
 end if;
 perform public.refresh_completion((now() at time zone 'Africa/Blantyre')::date);
end $$;
create or replace function public.guided_initialize(p_input jsonb,p_targets jsonb) returns void language plpgsql security invoker set search_path='' as $$
declare pg uuid; wk uuid; wt uuid; ex record; grp text; d integer; ord integer; idx integer:=0; days integer[]; eq jsonb; begin
 if auth.uid() is null then raise exception 'NOT_AUTHENTICATED';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,1));
 if exists(select 1 from public.profiles where user_id=auth.uid()) then return;end if;
 select array_agg(value::integer order by value::integer) into days from jsonb_array_elements_text(p_input->'days');
 if cardinality(days) not between 3 and 5 or (select count(distinct v) from unnest(days) v)<>cardinality(days) or exists(select 1 from unnest(days) v where v not between 0 and 6) then raise exception 'INVALID_INPUT';end if;
 eq:=p_input->'equipment';
 if not eq?'bodyweight' or exists(select 1 from jsonb_array_elements_text(eq) v where v not in ('bodyweight','barbell','dumbbell','cable','machine','pullup_bar','bench','incline_bench','squat_rack','lat_pulldown','seated_row','leg_press','leg_extension','leg_curl','chest_press')) then raise exception 'INVALID_INPUT';end if;
 perform public.initialize_profile(jsonb_build_object('name',p_input->>'name','height',p_input->'height','weight',p_input->'weight','goal',p_input->'goal'),p_targets,eq);
 update public.profiles set target_date=(start_date+make_interval(months=>(p_input->>'months')::integer))::date,training_days_per_week=cardinality(days) where user_id=auth.uid();
 update public.user_preferences set onboarding_context=p_input-'name'-'weight'-'height'-'goal'-'equipment'-'days',budget_mode=p_input->>'budget' where user_id=auth.uid();
 update public.nutrition_targets set reason='Estimated starting targets; modest surplus, adjusted only from logged progress' where user_id=auth.uid() and version=1;
 select id into pg from public.training_programs where user_id=auth.uid() and effective_to is null;
 select id into wk from public.program_weeks where training_program_id=pg;
 -- Initial templates have no sessions/history. Replace only this new account's draft.
 delete from public.workout_templates where program_week_id=wk and user_id=auth.uid();
 foreach d in array days loop
 idx:=idx+1;
 insert into public.workout_templates(user_id,program_week_id,name,day_of_week,sort_order) values(auth.uid(),wk,case when cardinality(days)=3 then 'Full body '||idx else case when mod(idx,2)=1 then 'Upper ' else 'Lower ' end||idx end,d,idx) returning id into wt;
 ord:=0;
 for grp in select unnest(case when cardinality(days)=3 then array['Quads','Hamstrings','Chest','Back','Shoulders','Core'] when mod(idx,2)=1 then array['Chest','Back','Shoulders','Biceps','Triceps'] else array['Quads','Hamstrings','Glutes','Calves','Core'] end) loop
 select e.* into ex from public.exercises e where e.is_active and e.primary_muscle=grp and public.can_use_exercise(e.id)
 order by case when e.equipment='bodyweight' then 1 else 0 end,e.slug limit 1;
 if ex.id is not null then
 insert into public.workout_template_exercises(user_id,workout_template_id,exercise_id,sort_order,sets,rep_min,rep_max,target_rir,rest_seconds) values(auth.uid(),wt,ex.id,ord,case when cardinality(days)=3 then 2 else 3 end,ex.default_rep_min,ex.default_rep_max,2,ex.default_rest_seconds);ord:=ord+1;
 end if;end loop;end loop;
 update public.training_programs set name=case when cardinality(days)=3 then 'Full body' else 'Upper / Lower' end where id=pg;
end $$;
revoke all on function public.guided_initialize(jsonb,jsonb) from public,anon;
grant execute on function public.guided_initialize(jsonb,jsonb) to authenticated;
update public.exercises set illustration_url='/exercises/barbell-bench-press-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.", "After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='barbell-bench-press';
update public.exercises set illustration_url='/exercises/incline-dumbbell-press-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.", "Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.", "Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='incline-dumbbell-press';
update public.exercises set illustration_url='/exercises/machine-chest-press-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Sit down on the Chest Press Machine and select the weight.", "Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.", "Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.", "Now bring the handles back towards you as you breathe in.", "Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.", "Repeat for the recommended amount of reps.", "When finished step on the lever again and slowly get the handles back to their original place."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='machine-chest-press';
update public.exercises set illustration_url='/exercises/cable-fly-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.", "Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='cable-fly';
update public.exercises set illustration_url='/exercises/push-up-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.", "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='push-up';
update public.exercises set illustration_url='/exercises/lat-pulldown-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.", "After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='lat-pulldown';
update public.exercises set illustration_url='/exercises/pull-up-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='pull-up';
update public.exercises set illustration_url='/exercises/barbell-row-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.", "Then inhale and slowly lower the barbell back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='barbell-row';
update public.exercises set illustration_url='/exercises/cable-row-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='cable-row';
update public.exercises set illustration_url='/exercises/dumbbell-row-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Choose a flat bench and place a dumbbell on each side of it.", "Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.", "Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.", "Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.", "Lower the resistance straight down to the starting position. Breathe in as you perform this step.", "Repeat the movement for the specified amount of repetitions.", "Switch sides and repeat again with the other arm."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='dumbbell-row';
update public.exercises set illustration_url='/exercises/chin-up-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.", "As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='chin-up';
update public.exercises set illustration_url='/exercises/overhead-press-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.", "Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.", "Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "Lower the bar down to the collarbone slowly as you inhale.", "Lift the bar back up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='overhead-press';
update public.exercises set illustration_url='/exercises/dumbbell-shoulder-press-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.", "Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.", "Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.", "Now, exhale and push the dumbbells upward until they touch at the top.", "Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='dumbbell-shoulder-press';
update public.exercises set illustration_url='/exercises/lateral-raise-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.", "While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbells back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='lateral-raise';
update public.exercises set illustration_url='/exercises/rear-delt-fly.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Hold light dumbbells, hinge at your hips, and keep your back neutral.", "With elbows slightly bent, lift arms out to the sides.", "Lower slowly without swinging your torso."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='rear-delt-fly';
update public.exercises set illustration_url='/exercises/pike-push-up.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Place hands shoulder-width apart and lift your hips into an inverted V.", "Bend your elbows to lower your head toward the floor between your hands.", "Press the floor away, keeping your hips high."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='pike-push-up';
update public.exercises set illustration_url='/exercises/face-pull-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='face-pull';
update public.exercises set illustration_url='/exercises/barbell-curl-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.", "While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.", "Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.", "Slowly begin to bring the bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='barbell-curl';
update public.exercises set illustration_url='/exercises/dumbbell-curl-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='dumbbell-curl';
update public.exercises set illustration_url='/exercises/hammer-curl-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.", "The palms of the hands should be facing your torso. This will be your starting position.", "Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.", "After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='hammer-curl';
update public.exercises set illustration_url='/exercises/cable-curl-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.", "While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.", "Slowly begin to bring the curl bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='cable-curl';
update public.exercises set illustration_url='/exercises/triceps-pushdown-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.", "Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='triceps-pushdown';
update public.exercises set illustration_url='/exercises/overhead-triceps-extension-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.", "The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.", "Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.", "Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='overhead-triceps-extension';
update public.exercises set illustration_url='/exercises/close-grip-push-up.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Set your hands just inside shoulder width, with legs extended and body straight.", "Lower your chest while keeping elbows near your sides.", "Push back up without letting your lower back sag."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='close-grip-push-up';
update public.exercises set illustration_url='/exercises/dumbbell-skullcrusher.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Lie on a flat bench holding dumbbells above your chest, palms facing each other.", "Keep upper arms steady and bend elbows to lower the weights beside your head.", "Straighten your elbows with control; use a light load."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='dumbbell-skullcrusher';
update public.exercises set illustration_url='/exercises/back-squat-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='back-squat';
update public.exercises set illustration_url='/exercises/leg-press-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='leg-press';
update public.exercises set illustration_url='/exercises/bulgarian-split-squat-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Position yourself into a staggered stance with the rear foot elevated and front foot forward.", "Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.", "Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.", "At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='bulgarian-split-squat';
update public.exercises set illustration_url='/exercises/leg-extension-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.", "Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.", "Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.", "Repeat for the recommended amount of times."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='leg-extension';
update public.exercises set illustration_url='/exercises/bodyweight-squat-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.", "Begin the movement by flexing your knees and hips, sitting back with your hips.", "Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='bodyweight-squat';
update public.exercises set illustration_url='/exercises/goblet-squat-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.", "Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.", "At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='goblet-squat';
update public.exercises set illustration_url='/exercises/romanian-deadlift-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.", "Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.", "Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.", "Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='romanian-deadlift';
update public.exercises set illustration_url='/exercises/leg-curl-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.", "Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.", "As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='leg-curl';
update public.exercises set illustration_url='/exercises/dumbbell-romanian-deadlift.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Stand tall with dumbbells in front of your thighs and knees softly bent.", "Push hips back, keeping weights close and your back neutral. Stop when hamstrings feel tension.", "Drive through your feet and bring hips forward to stand."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='dumbbell-romanian-deadlift';
update public.exercises set illustration_url='/exercises/single-leg-glute-bridge-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Lay on the floor with your feet flat and knees bent.", "Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.", "Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.", "Extend as far as possible, pause and then return to the starting position."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='single-leg-glute-bridge';
update public.exercises set illustration_url='/exercises/hip-thrust-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.", "Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.", "Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='hip-thrust';
update public.exercises set illustration_url='/exercises/glute-bridge.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Lie on your back with knees bent and feet flat, about hip-width apart.", "Press through your feet to lift your hips until shoulders, hips and knees line up.", "Squeeze your glutes, then lower slowly without arching your back."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='glute-bridge';
update public.exercises set illustration_url='/exercises/reverse-lunge.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Stand tall holding dumbbells by your sides.", "Step one foot back and bend both knees, keeping your front foot flat.", "Push through your front foot to return. Alternate sides."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='reverse-lunge';
update public.exercises set illustration_url='/exercises/bodyweight-reverse-lunge.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Stand tall with feet hip-width apart.", "Step one foot back and lower until both knees bend comfortably.", "Push through the front foot to stand. Alternate sides."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='bodyweight-reverse-lunge';
update public.exercises set illustration_url='/exercises/standing-calf-raise-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Adjust the padded lever of the calf raise machine to fit your height.", "Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.", "Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='standing-calf-raise';
update public.exercises set illustration_url='/exercises/seated-calf-raise.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Sit on a stable bench with knees near 90 degrees and feet flat. Place dumbbells securely on your thighs above the knees.", "Lift your heels while keeping the balls of your feet on the floor.", "Pause briefly and lower heels slowly."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='seated-calf-raise';
update public.exercises set illustration_url='/exercises/plank-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='plank';
update public.exercises set illustration_url='/exercises/hanging-leg-raise-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.", "Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.", "Go back slowly to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='hanging-leg-raise';
update public.exercises set illustration_url='/exercises/cable-crunch-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Kneel below a high pulley that contains a rope attachment.", "Grasp cable rope attachment and lower the rope until your hands are placed next to your face.", "Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.", "With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.", "Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.", "Repeat for the recommended amount of repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='cable-crunch';
update public.exercises set illustration_url='/exercises/dead-bug-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration',instructions='["Begin lying on your back with your hands extended above you toward the ceiling.", "Bring your feet, knees, and hips up to 90 degrees.", "Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.", "Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.", "Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.", "Stay tight and return the working leg to the starting position.", "Repeat on the opposite side, alternating until the set is complete."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='dead-bug';
update public.exercises set illustration_url='/exercises/lying-leg-raise.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Lie on your back with arms by your sides and legs extended.", "Keep your lower back gently pressed toward the floor and raise your legs.", "Lower only as far as you can without arching your back; bend knees to make it easier."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='lying-leg-raise';
update public.exercises set illustration_url='/exercises/prone-reverse-snow-angel.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Lie face down with arms by your hips, palms facing the floor.", "Lift your arms slightly and sweep them out and overhead in a comfortable arc.", "Return slowly without lifting your chest or shrugging."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='prone-reverse-snow-angel';
update public.exercises set illustration_url='/exercises/self-resisted-biceps-curl.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Stand with one elbow close to your ribs and palm facing up. Place your other hand over that wrist.", "Curl upward while your opposite hand applies smooth downward resistance.", "Lower slowly against resistance, then switch arms."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='self-resisted-biceps-curl';
